from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
PY = ROOT / "reference" / "python"


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"expected one match in {path}, found {count}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


def regex_once(path: Path, pattern: str, replacement: str) -> None:
    text = path.read_text(encoding="utf-8")
    updated, count = re.subn(pattern, replacement, text, count=1, flags=re.S)
    if count != 1:
        raise RuntimeError(f"expected one regex match in {path}, found {count}")
    path.write_text(updated, encoding="utf-8")


# DataStore: allow full reads and add an explicit retention primitive.
datastore = PY / "fresnica" / "datastore.py"
replace_once(
    datastore,
    '''    @abstractmethod\n    def get_operations(\n        self, network: str, account: str, limit: int = 20\n    ) -> list[dict]:\n        raise NotImplementedError\n''',
    '''    @abstractmethod\n    def get_operations(\n        self, network: str, account: str, limit: int | None = 20\n    ) -> list[dict]:\n        raise NotImplementedError\n\n    @abstractmethod\n    def trim_operations(self, network: str, account: str, limit: int) -> int:\n        """Keep only the newest ``limit`` operations and return rows removed."""\n        raise NotImplementedError\n''',
)
replace_once(
    datastore,
    '''    def get_operations(\n        self, network: str, account: str, limit: int = 20\n    ) -> list[dict]:\n        items = list(self._operations.get((network, account), {}).values())\n        items.sort(\n            key=lambda item: int(item.get("paging_token", item.get("id", 0)) or 0),\n            reverse=True,\n        )\n        return items[:limit]\n''',
    '''    def get_operations(\n        self, network: str, account: str, limit: int | None = 20\n    ) -> list[dict]:\n        items = list(self._operations.get((network, account), {}).values())\n        items.sort(\n            key=lambda item: int(item.get("paging_token", item.get("id", 0)) or 0),\n            reverse=True,\n        )\n        return items if limit is None else items[:limit]\n\n    def trim_operations(self, network: str, account: str, limit: int) -> int:\n        if limit < 0:\n            raise ValueError("Operation retention limit must be non-negative")\n        key = (network, account)\n        bucket = self._operations.get(key, {})\n        if len(bucket) <= limit:\n            return 0\n        tokens = sorted(bucket, key=lambda value: int(value or 0), reverse=True)\n        keep = set(tokens[:limit])\n        removed = len(bucket) - len(keep)\n        self._operations[key] = {token: item for token, item in bucket.items() if token in keep}\n        return removed\n''',
)
replace_once(
    datastore,
    '''    def get_operations(\n        self, network: str, account: str, limit: int = 20\n    ) -> list[dict]:\n        with self._connect() as db:\n            rows = db.execute(\n                """\n                SELECT raw_json FROM operations\n                WHERE network = ? AND account = ?\n                ORDER BY CAST(paging_token AS INTEGER) DESC\n                LIMIT ?\n                """,\n                (network, account, limit),\n            ).fetchall()\n        return [json.loads(row["raw_json"]) for row in rows]\n''',
    '''    def get_operations(\n        self, network: str, account: str, limit: int | None = 20\n    ) -> list[dict]:\n        with self._connect() as db:\n            if limit is None:\n                rows = db.execute(\n                    """\n                    SELECT raw_json FROM operations\n                    WHERE network = ? AND account = ?\n                    ORDER BY CAST(paging_token AS INTEGER) DESC\n                    """,\n                    (network, account),\n                ).fetchall()\n            else:\n                rows = db.execute(\n                    """\n                    SELECT raw_json FROM operations\n                    WHERE network = ? AND account = ?\n                    ORDER BY CAST(paging_token AS INTEGER) DESC\n                    LIMIT ?\n                    """,\n                    (network, account, limit),\n                ).fetchall()\n        return [json.loads(row["raw_json"]) for row in rows]\n\n    def trim_operations(self, network: str, account: str, limit: int) -> int:\n        if limit < 0:\n            raise ValueError("Operation retention limit must be non-negative")\n        with self._connect() as db:\n            if limit == 0:\n                cursor = db.execute(\n                    "DELETE FROM operations WHERE network = ? AND account = ?",\n                    (network, account),\n                )\n            else:\n                cursor = db.execute(\n                    """\n                    DELETE FROM operations\n                    WHERE network = ? AND account = ?\n                      AND paging_token NOT IN (\n                          SELECT paging_token FROM operations\n                          WHERE network = ? AND account = ?\n                          ORDER BY CAST(paging_token AS INTEGER) DESC\n                          LIMIT ?\n                      )\n                    """,\n                    (network, account, network, account, limit),\n                )\n            return max(0, cursor.rowcount)\n''',
)

